from common import *
p=Pt(7)
p.P("""Le tableau clinique du syndrome d'Ogilvie se décompose en cinq syndromes que le clinicien reconnaît séparément, car chacun a son mécanisme et appelle sa propre action. Pour chaque syndrome, cette partie donne les signes fonctionnels, les signes physiques, le geste de recherche et le mécanisme.""")
p.H("7.1 Le syndrome de distension colique")
p.P("""Le [[1]] est le syndrome central, puisque la maladie se révèle par un ventre qui se tend. Les signes fonctionnels sont la sensation de ballonnement, l'inconfort abdominal et la douleur d'intensité variable{w1306ed-5}. Les signes physiques sont une distension globale, un abdomen tympanique et un rectum capacieux{wd21b7d-178}. Le geste de recherche est l'inspection de face et de profil, la percussion et la mesure du périmètre abdominal, répétées à heure fixe. Le mécanisme est l'accumulation de gaz dans un côlon dont la propulsion est insuffisante{wd21b7d-184}.""", wins={1:("syndrome de distension colique","""Le syndrome de distension colique désigne l'augmentation du calibre du côlon par accumulation de gaz et de liquide. Dans le syndrome d'Ogilvie, la dilatation est massive et sans obstacle mécanique{w1306ed-4}. Le diamètre du cæcum la quantifie : 9 à 12 cm fait craindre une perforation imminente{wd21b7d-181}.""")})
p.H("7.2 Le syndrome occlusif fonctionnel")
p.P("""Le [[2]] imite l'occlusion vraie sans en avoir la cause, ce qui explique les erreurs d'indication. Les signes fonctionnels sont l'arrêt des matières et des gaz, les nausées et les vomissements{w1306ed-5 wd21b7d-179}. Les signes physiques sont la réduction ou l'absence d'émission de gaz{wd21b7d-178}. Le geste de recherche est le toucher rectal et l'interrogatoire sur la date des dernières selles et des derniers gaz. Le mécanisme est un trouble de la motricité, et non un obstacle{w72d527-2}. Comme les signes sont identiques à ceux d'une occlusion mécanique, le scanner reste indispensable{wd21b7d-179}.""", wins={2:("syndrome occlusif fonctionnel","""Le syndrome occlusif fonctionnel associe arrêt du transit et distension sans obstacle : l'iléus paralytique et la pseudo-obstruction colique aiguë en sont les deux causes que cite le protocole vaudois{w1306ed-4}. Il s'oppose au syndrome occlusif mécanique, causé par un obstacle ou une torsion{w1306ed-4}.""")})
p.H("7.3 Le syndrome de souffrance pariétale et de perforation")
p.P("""Le [[3]] est le signal qui fait passer à l'urgence chirurgicale. Les signes fonctionnels sont une douleur abdominale réfractaire{w1306ed-5}. Les signes physiques sont le péritonisme, un abdomen « de bois » et une fièvre{w1306ed-7 w7aa533-4}. Le geste de recherche est la palpation douce du cæcum puis la recherche d'une défense. Le mécanisme est la tension excessive de la paroi dilatée, qui mène à l'ischémie puis à la perforation{wd21b7d-181 w1306ed-5}. Le scanner confirme alors un pneumopéritoine ou une pneumatose{w1306ed-6}.""", wins={3:("syndrome de souffrance pariétale","""Le syndrome de souffrance pariétale regroupe les signes d'ischémie et de perforation du côlon dilaté. Il est la complication qui fait monter la mortalité jusqu'à 50 %{w72d527-3}. Le protocole vaudois en cite les manifestations : ischémie colique, translocation bactérienne, perforation locale ou diastatique, péritonite, choc{w1306ed-5}.""")})
p.H("7.4 Le syndrome métabolique et ionique")
p.P("""Le [[4]] est à la fois une cause et une conséquence, car l'ionogramme perturbé freine le côlon qui en retour aggrave les pertes. Les signes fonctionnels sont les vomissements et la diarrhée, qui font perdre potassium et eau{wf45af4-12}. Les signes physiques sont ceux d'un patient déshydraté et fragile, avec une insuffisance rénale aiguë fréquente{wd21b7d-180}. Le geste de recherche est le prélèvement sanguin : sodium, potassium, calcium, créatinine, gaz du sang et lactates{w1306ed-5}. Le mécanisme est la perturbation de la contraction du muscle lisse colique par les déséquilibres du calcium, du magnésium et du potassium{wf45af4-12 wd21b7d-184}.""", wins={4:("syndrome métabolique et ionique","""Le syndrome métabolique et ionique regroupe les troubles de l'eau, des électrolytes et de l'équilibre acido-basique. Une diarrhée sécrétoire peut produire une acidose métabolique sans trou anionique par perte de bicarbonate{wf45af4-12}. Le consensus britannique demande de contrôler et de corriger le calcium, le magnésium, le potassium et le sodium{wd21b7d-184}.""")})
p.H("7.5 Le syndrome cholinergique du traitement")
p.P("""Le [[5]] n'est pas celui de la maladie mais celui de son traitement, c'est pourquoi il faut le connaître avant de prescrire la néostigmine. Les signes fonctionnels et physiques d'excès cholinergique sont la bradycardie, les troubles du rythme, l'hypersécrétion oropharyngée et respiratoire, l'augmentation de l'activité gastro-intestinale, l'agitation et les crampes musculaires{aips-49389-13}. Le geste de recherche est le monitorage cardiaque continu pendant et après l'administration{wd21b7d-186}. Le mécanisme est l'excès d'acétylcholine aux synapses muscariniques, que l'atropine antagonise{aips-49389-16}.""", wins={5:("syndrome cholinergique","""Le syndrome cholinergique est l'ensemble des effets muscariniques d'un excès d'acétylcholine. L'information professionnelle suisse de la néostigmine cite la bradycardie, l'augmentation des sécrétions oropharyngées, la stimulation de l'activité du tube digestif et les bronchospasmes, que l'on peut supprimer par l'administration d'atropine{aips-49389-16}.""")})
p.T(["Syndrome","Signes fonctionnels","Signes physiques"],[
["7.1 Distension colique","Ballonnement, douleur variable {w1306ed-5}","Ventre tendu, tympanique, rectum capacieux {wd21b7d-178}"],
["7.2 Occlusif fonctionnel","Arrêt des matières et des gaz, vomissements {w1306ed-5}","Émission de gaz réduite ou absente {wd21b7d-178}"],
["7.3 Souffrance pariétale","Douleur réfractaire {w1306ed-5}","Péritonisme, fièvre, choc {w7aa533-4 w1306ed-5}"],
["7.4 Métabolique et ionique","Vomissements, diarrhée {wf45af4-12}","Déshydratation, insuffisance rénale {wd21b7d-180}"],
["7.5 Cholinergique (traitement)","Crampes, agitation {aips-49389-13}","Bradycardie, hypersécrétion {aips-49389-13}"]])
p.P("""Le tableau permet de passer du symptôme à l'action. Un ventre distendu sans signe de souffrance relève de la surveillance, alors qu'un syndrome de souffrance pariétale relève du scanner et du chirurgien.""")
p.save()
